if(PHP_SAPI!=='cli'||!getenv('CC_DB_PASSWORD'))exit(1);define('MODX_API_MODE',true);ob_start();require '/var/www/html/index.php';while(ob_get_level())ob_end_clean();if($modx->getOption('dbname')!=='cookie_consent_test')exit(1);
